########## parse.mjs ##########
// X ships more than one shape for the same data, so every accessor here is
// defensive: an entry we cannot read is skipped, never thrown on. Returning a
// short list is recoverable; crashing the poll loop is not.

function toIso(twitterDate) {
  // X sends "Tue Aug 18 14:02:11 +0000 2026", which Date parses correctly.
  const parsed = new Date(twitterDate);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function unwrapTweet(result) {
  if (!result || typeof result !== 'object') return null;
  // TweetWithVisibilityResults nests the real tweet one level down.
  const tweet = result.__typename === 'TweetWithVisibilityResults' ? result.tweet : result;
  if (!tweet || typeof tweet !== 'object') return null;
  return tweet;
}

function screenNameOf(tweet) {
  const user = tweet?.core?.user_results?.result;
  // Newer payloads put it under `core`, older ones under `legacy`.
  return user?.core?.screen_name || user?.legacy?.screen_name || null;
}

// X migrated the author counters out of `user.legacy` (now empty on live
// payloads) into `relationship_counts`. Both are read so an older payload
// shape, and the hand-built fixtures, keep working.
function authorSignal(tweet) {
  const user = tweet?.core?.user_results?.result ?? {};
  const followers = user?.relationship_counts?.followers ?? user?.legacy?.followers_count ?? null;
  const followedBy = user?.relationship_perspectives?.followed_by;
  return {
    followers: typeof followers === 'number' ? followers : null,
    // Whether this account follows @entirehq. Undefined means the payload did
    // not say, which must not be read as "does not follow us".
    followsUs: typeof followedBy === 'boolean' ? followedBy : null,
    verified: Boolean(user?.is_blue_verified || user?.verification?.verified),
  };
}

function entriesOf(payload) {
  const instructions =
    payload?.data?.search_by_raw_query?.search_timeline?.timeline?.instructions;
  if (!Array.isArray(instructions)) return [];
  return instructions
    .filter((i) => i?.type === 'TimelineAddEntries' && Array.isArray(i.entries))
    .flatMap((i) => i.entries);
}

// notify-slack.mjs interpolates `author` and `id` straight into a Slack
// link construct (`<url|text>`); a value containing `|` or `>` would break
// out of that syntax. X enforces this handle/id shape server-side, so this
// is defense in depth rather than a live exploit — but the guarantee
// downstream code relies on needs to be enforced where the data enters, not
// just assumed.
const HANDLE_RE = /^[A-Za-z0-9_]{1,15}$/;
const ID_RE = /^\d+$/;

export function parseTimelineJson(payload) {
  const tweets = [];
  const seenIds = new Set();
  for (const entry of entriesOf(payload)) {
    const tweet = unwrapTweet(entry?.content?.itemContent?.tweet_results?.result);
    if (!tweet) continue;

    const id = tweet.rest_id;
    const author = screenNameOf(tweet);
    const legacy = tweet.legacy;
    if (!id || !author || !legacy) continue;
    if (!HANDLE_RE.test(author) || !ID_RE.test(String(id))) continue;

    const createdAt = toIso(legacy.created_at);
    if (!createdAt) continue;

    // X can fire more than one SearchTimeline response per navigation (and a
    // single payload can carry more than one TimelineAddEntries instruction),
    // so the same tweet can arrive twice. Without this, a duplicate inflates
    // "tracking N" / "N tracked" counts even though nothing new happened.
    const idStr = String(id);
    if (seenIds.has(idStr)) continue;
    seenIds.add(idStr);

    tweets.push({
      id: idStr,
      author,
      text: legacy.full_text ?? '',
      url: `https://x.com/${author}/status/${id}`,
      createdAt,
      inReplyToStatusId: legacy.in_reply_to_status_id_str ?? null,
      isQuoteStatus: Boolean(legacy.is_quote_status),
      ...authorSignal(tweet),
    });
  }
  return tweets;
}

const STATUS_PATH_RE = /^(?:https?:\/\/(?:x|twitter)\.com)?\/([A-Za-z0-9_]{1,15})\/status\/(\d+)/;

// The DOM path can see that a "Replying to" block was rendered but not which
// status is being replied to. This sentinel says "a parent exists, identity
// unknown" — filter.mjs only ever checks presence, never the value.
export const UNKNOWN_PARENT = 'unknown';

export function parseDomRecords(records) {
  if (!Array.isArray(records)) return [];
  const tweets = [];
  const seen = new Set();

  for (const record of records) {
    if (!record || typeof record !== 'object') continue;

    const match = typeof record.permalink === 'string' && record.permalink.match(STATUS_PATH_RE);
    if (!match) continue;
    const [, pathAuthor, id] = match;

    if (seen.has(id)) continue;

    const createdAt = typeof record.datetime === 'string' ? toIso(record.datetime) : null;
    if (!createdAt) continue;

    // Prefer the permalink's author: the rendered handle can belong to a
    // quoted or retweeting account rather than the tweet's own author.
    const author = pathAuthor;

    seen.add(id);
    tweets.push({
      id,
      author,
      text: typeof record.text === 'string' ? record.text : '',
      url: `https://x.com/${author}/status/${id}`,
      createdAt,
      inReplyToStatusId: record.hasReplyingTo ? UNKNOWN_PARENT : null,
      isQuoteStatus: Boolean(record.hasQuotedTweet),
    });
  }
  return tweets;
}
########## filter.mjs ##########
function classify(rawTweet) {
  // Reply beats quote: a quoted reply is still a reply to something of ours,
  // which is the more actionable framing.
  if (rawTweet.inReplyToStatusId) return 'reply';
  if (rawTweet.isQuoteStatus) return 'quote';
  return 'mention';
}

export function filterAndClassify(rawTweets, ownHandle) {
  if (!Array.isArray(rawTweets)) return [];
  const own = String(ownHandle || '').replace(/^@/, '').toLowerCase();

  return rawTweets
    .filter((t) => {
      return (
        t &&
        typeof t === 'object' &&
        t.id &&
        t.author &&
        typeof t.text === 'string' &&
        typeof t.url === 'string' &&
        t.url &&
        !Number.isNaN(new Date(t.createdAt).getTime())
      );
    })
    .filter((t) => t.author.toLowerCase() !== own)
    .map((t) => ({
      id: t.id,
      author: t.author,
      text: t.text,
      url: t.url,
      createdAt: t.createdAt,
      kind: classify(t),
      followers: t.followers ?? null,
      followsUs: t.followsUs ?? null,
      verified: t.verified ?? false,
    }))
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
}
########## score.mjs ##########
export const PRIORITY_THRESHOLD = 4;

const QUESTION_RE = /\?/;
const COMPETITOR_RE = /\b(github|gitlab|bitbucket|cursor|origin|forgejo|gitea|sourcehut)\b/i;
const INTENT_RE = /\b(switch(ing|ed)?|migrat(e|ing|ed)|mov(e|ing|ed) (off|from|to)|replac(e|ing)|try(ing)?|signed up|onboard(ing)?|self-?host)\b/i;

function normalize(handle) {
  return String(handle || '').trim().replace(/^@/, '').trim().toLowerCase();
}

export function parseHandleList(raw) {
  return String(raw || '')
    .split(',')
    .map(normalize)
    .filter(Boolean);
}

// Engagement counts are deliberately absent. A mention is seen within one poll
// of being posted, when every tweet still reads 0 likes and ~20 views, so
// scoring on traction would rank everything identically at exactly the moment
// the decision has to be made. Author reach is known immediately; traction is
// not.
export function scoreTweet(tweet, { teamHandles = [] } = {}) {
  const reasons = [];
  let score = 0;

  const followers = Number(tweet.followers) || 0;
  if (followers >= 10000) {
    score += 3;
    reasons.push(`${Math.round(followers / 1000)}k followers`);
  } else if (followers >= 2000) {
    score += 2;
    reasons.push(`${(followers / 1000).toFixed(1)}k followers`);
  }

  // Someone already following @entirehq is part of the existing audience. A
  // mention from outside it is reach we do not already have.
  if (tweet.followsUs === false) {
    score += 2;
    reasons.push('not a follower');
  }

  if (QUESTION_RE.test(tweet.text || '')) {
    score += 2;
    reasons.push('question');
  }

  if (tweet.kind === 'quote') {
    score += 2;
    reasons.push('quote tweet');
  } else if (tweet.kind === 'mention') {
    score += 1;
    reasons.push('standalone mention');
  }

  if (COMPETITOR_RE.test(tweet.text || '') && INTENT_RE.test(tweet.text || '')) {
    score += 2;
    reasons.push('switching intent');
  }

  if (tweet.verified) score += 1;

  if (teamHandles.includes(normalize(tweet.author))) {
    score -= 5;
    reasons.push('team account');
  }

  return { score, reasons };
}

export function isTeam(author, teamHandles = []) {
  return teamHandles.includes(normalize(author));
}
########## tier.mjs ##########
import { PRIORITY_THRESHOLD, scoreTweet, isTeam } from './score.mjs';

export const PRIORITY = 'priority';
export const ROUTINE = 'routine';
export const MUTED = 'muted';

// The two signals answer different questions and neither subsumes the other:
// the score measures reach (how many people see this), the classifier measures
// intent (is this worth answering). Either one alone mis-ranks a common case —
// a thoughtful support question from a 200-follower account, or an emoji reply
// from someone with 40k.
export function decideTier({ tweet, score, reasons, verdict, mutedHandles = [], teamHandles = [] }) {
  if (isTeam(tweet.author, mutedHandles)) {
    return { tier: MUTED, reasons: ['muted account'], verdict: null };
  }

  const onTeam = isTeam(tweet.author, teamHandles);
  const llm = verdict?.ok ? verdict.tier : null;
  const combined = [...reasons];
  if (verdict?.ok && verdict.reason) combined.push(verdict.reason);

  // A team member's own reply is a receipt, never a call to action.
  if (onTeam) return { tier: ROUTINE, reasons: combined, verdict: llm };

  // A verdict wins whenever the classifier actually read the text. The score
  // measures reach, and reach does not make an emoji reply worth answering —
  // letting a high score override an explicit ROUTINE put eleven emoji
  // tag-chain replies from one 2.2k-follower account into priority on the
  // first live run. IGNORE is demoted rather than dropped: a false negative on
  // a real support question would be invisible, and silence is the one failure
  // this tool exists to prevent.
  if (llm === 'ROUTINE' || llm === 'IGNORE') return { tier: ROUTINE, reasons: combined, verdict: llm };

  if (llm === 'PRIORITY') return { tier: PRIORITY, reasons: combined, verdict: llm };

  // No usable verdict (classifier off, errored, or timed out): the score
  // decides alone. This is the degraded path and it is meant to still work.
  if (score >= PRIORITY_THRESHOLD) return { tier: PRIORITY, reasons: combined, verdict: llm };

  return { tier: ROUTINE, reasons: combined, verdict: llm };
}

export function triage(tweet, { mutedHandles = [], teamHandles = [], verdict = null } = {}) {
  const { score, reasons } = scoreTweet(tweet, { teamHandles });
  return { ...decideTier({ tweet, score, reasons, verdict, mutedHandles, teamHandles }), score };
}

########## notify-slack.mjs ##########
const VERB = {
  mention: 'mentioned',
  reply: 'replied to',
  quote: 'quoted',
};

const MAX_BODY = 500;

// Slack mrkdwn treats these three as control characters. Tweet text is
// untrusted input — without this a tweet could forge a link in our channel.
export function escapeSlack(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function body(text) {
  const flat = String(text).replace(/\s+/g, ' ').trim();
  return flat.length > MAX_BODY ? `${flat.slice(0, MAX_BODY - 1)}…` : flat;
}

function reach(tweet) {
  const n = Number(tweet.followers);
  if (!Number.isFinite(n) || n <= 0) return null;
  if (n >= 10000) return `${Math.round(n / 1000)}k followers`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k followers`;
  return `${n} followers`;
}

function meta(tweet, triage) {
  const r = reach(tweet);
  const reasons = (triage?.reasons ?? []).filter((x) => x !== r);
  return reasons.slice(0, 3).join(', ') || tweet.kind;
}

// Priority gets the full card and a leading marker; routine collapses to one
// line. The whole point of the split is that a skimming reader can tell them
// apart without reading either, so the shapes must differ, not just the words.
// The kind leads every line, in the same slot on both tiers, so scanning the
// left edge answers "reply or tweet?" without reading the line. It used to sit
// mid-chain in the trailing metadata, where it was effectively invisible.
const KIND_LABEL = {
  mention: 'TWEET',
  reply: 'REPLY',
  quote: 'QUOTE',
};

export function kindLabel(kind) {
  return KIND_LABEL[kind] ?? 'TWEET';
}

export function buildTweetMessage(tweet, triage = null) {
  const verb = VERB[tweet.kind] ?? 'mentioned';
  const epoch = Math.floor(new Date(tweet.createdAt).getTime() / 1000);
  const handle = escapeSlack(tweet.author);
  const profile = `https://x.com/${encodeURIComponent(tweet.author)}`;
  const label = kindLabel(tweet.kind);
  const r = reach(tweet);

  if (triage && triage.tier === 'routine') {
    return {
      text: `${label} \u00b7 @${handle} ${verb} @entirehq`,
      blocks: [
        {
          type: 'context',
          elements: [
            {
              type: 'mrkdwn',
              text:
                `\`${label}\` <${profile}|@${handle}> \u00b7 ` +
                `${escapeSlack(body(tweet.text).slice(0, 140))} \u00b7 ` +
                [`<${tweet.url}|open>`, r].filter(Boolean).join(' \u00b7 '),
            },
          ],
        },
      ],
    };
  }

  return {
    text: `\u2605 ${label} \u00b7 @${handle} ${verb} @entirehq`,
    blocks: [
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text:
            `*\u2605 \`${label}\`* <${profile}|@${handle}>` +
            (r ? ` \u00b7 ${r}` : '') +
            `\n>${escapeSlack(body(tweet.text))}`,
        },
      },
      {
        type: 'context',
        elements: [
          {
            type: 'mrkdwn',
            text:
              `<${tweet.url}|View on X> \u00b7 ${escapeSlack(meta(tweet, triage))} \u00b7 ` +
              `<!date^${epoch}^{date_short_pretty} at {time}|${tweet.createdAt}>`,
          },
        ],
      },
    ],
  };
}

export function buildAlertMessage(text) {
  return {
    text,
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text: escapeSlack(text) } }],
  };
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Resolves rather than rejects: the caller is a poll loop that must survive a
// bad Slack day, and the terminal has already shown the user this tweet.
export async function postToSlack(webhookUrl, payload, options = {}) {
  const { fetchImpl = fetch, retryDelayMs = 1000 } = options;
  let status = 0;

  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const response = await fetchImpl(webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
      });
      status = response.status;
      if (response.ok) return { ok: true, status, attempts: attempt };
    } catch {
      status = 0;
    }
    if (attempt === 1) await sleep(retryDelayMs);
  }

  return { ok: false, status, attempts: 2 };
}
########## classify.mjs ##########
import Anthropic from '@anthropic-ai/sdk';

export const MODEL = 'claude-haiku-5-5';

const SYSTEM = `You triage public X/Twitter mentions of @entirehq, a git hosting platform built for AI coding agents, founded by GitHub's former CEO.

Judge whether the @entirehq team should act on a mention right now. Act means: reply, repost, or route it to someone internally.

PRIORITY: a question or support request aimed at the product; a user reporting a real problem; a notable endorsement worth reposting; someone comparing @entirehq to a competitor or saying they are switching; a request for access or a demo.
ROUTINE: generic praise, emoji-only replies, tangential mentions in an unrelated thread, pile-on replies that add nothing, chatter between other people where @entirehq is incidental.
IGNORE: spam, crypto/airdrop bait, unrelated accounts that merely contain the string, engagement farming.

Judge the text on its own merits. Follower counts are scored separately and must not influence this call.`;

const TOOL = {
  name: 'record_triage',
  description: 'Record the triage decision for one mention.',
  strict: true,
  input_schema: {
    type: 'object',
    properties: {
      tier: { type: 'string', enum: ['PRIORITY', 'ROUTINE', 'IGNORE'] },
      reason: { type: 'string', description: 'At most eight words, lowercase, no trailing period.' },
    },
    required: ['tier', 'reason'],
    additionalProperties: false,
  },
};

export function buildPrompt(tweet) {
  return [
    `Author: @${tweet.author}`,
    `Kind: ${tweet.kind}`,
    `Text: ${tweet.text}`,
  ].join('\n');
}

// Resolves rather than rejects. The caller is a poll loop whose deterministic
// score is a complete answer on its own, so a classifier outage degrades the
// tiering instead of dropping the notification.
export async function classify(tweet, { client, timeoutMs = 15000 } = {}) {
  if (!client) return { ok: false, tier: null, reason: null, error: 'no client' };

  try {
    const response = await client.messages.create(
      {
        model: MODEL,
        max_tokens: 256,
        system: SYSTEM,
        output_config: { effort: 'low' },
        tools: [TOOL],
        tool_choice: { type: 'tool', name: TOOL.name },
        messages: [{ role: 'user', content: buildPrompt(tweet) }],
      },
      { timeout: timeoutMs },
    );

    if (response.stop_reason === 'refusal') {
      return { ok: false, tier: null, reason: null, error: 'refusal' };
    }

    const call = response.content.find((block) => block.type === 'tool_use');
    if (!call) return { ok: false, tier: null, reason: null, error: 'no tool_use block' };

    const { tier, reason } = call.input ?? {};
    if (!['PRIORITY', 'ROUTINE', 'IGNORE'].includes(tier)) {
      return { ok: false, tier: null, reason: null, error: `bad tier: ${tier}` };
    }
    return { ok: true, tier, reason: String(reason ?? '').slice(0, 80) };
  } catch (err) {
    return { ok: false, tier: null, reason: null, error: err?.message ?? String(err) };
  }
}

export function createClient(apiKey) {
  return apiKey ? new Anthropic({ apiKey }) : null;
}
########## preview.mjs ##########
import { loadConfig, loadEnvFile, getProjectDir } from './config.mjs';
import { scrapeSearch } from './x-scrape.mjs';
import { filterAndClassify } from './filter.mjs';
import { triage, MUTED, PRIORITY } from './tier.mjs';
import { classify, createClient } from './classify.mjs';
import { printWarning } from './notify-terminal.mjs';

loadEnvFile(getProjectDir());

let config;
try {
  config = loadConfig();
} catch (err) {
  printWarning(err.message);
  process.exit(1);
}

const { mutedHandles, teamHandles } = config;
const { source, tweets } = await scrapeSearch(config);
const classified = filterAndClassify(tweets, config.ownHandle);
const client = createClient(config.anthropicApiKey);

console.log(
  `source=${source} tweets=${classified.length} ` +
    `muted=[${mutedHandles.join(',') || '-'}] team=[${teamHandles.join(',') || '-'}] ` +
    `classifier=${client ? 'on' : 'off'}\n`,
);

let calls = 0;
const rows = [];
for (const tweet of classified) {
  const pre = triage(tweet, { mutedHandles, teamHandles });
  let verdict = null;
  if (pre.tier !== MUTED && client) {
    verdict = await classify(tweet, { client });
    calls += 1;
    if (!verdict.ok) console.log(`  !! classify failed: ${verdict.error}`);
  }
  rows.push({ tweet, decision: triage(tweet, { mutedHandles, teamHandles, verdict }), verdict });
}

for (const { tweet, decision, verdict } of rows) {
  const mark = decision.tier === PRIORITY ? '*' : decision.tier === MUTED ? '-' : ' ';
  const llm = (verdict?.ok ? verdict.tier : 'n/a').padEnd(8);
  console.log(
    `${mark} ${decision.tier.padEnd(8)} score=${String(decision.score).padStart(2)} llm=${llm} ` +
      `@${tweet.author.padEnd(17)} f=${String(tweet.followers ?? '?').padStart(6)} ` +
      tweet.text.replace(/\s+/g, ' ').slice(0, 56),
  );
  if (verdict?.ok && verdict.reason) console.log(`${' '.repeat(15)}${verdict.reason}`);
}

const counts = rows.reduce((acc, r) => ({ ...acc, [r.decision.tier]: (acc[r.decision.tier] || 0) + 1 }), {});
console.log(`\ntiers: ${JSON.stringify(counts)} | classifier calls: ${calls}`);
console.log('Nothing was posted to Slack and no state was written.');
########## check.mjs ##########
// One live scrape, printed, notifying nobody. This is the manual gate before
// the watcher is considered working.
import { loadConfig, loadEnvFile, getProjectDir, ConfigError } from './config.mjs';
import { filterAndClassify } from './filter.mjs';
import { formatTweet, printWarning, printQuiet } from './notify-terminal.mjs';
import { scrapeSearch } from './x-scrape.mjs';

loadEnvFile(getProjectDir());

let config;
try {
  config = loadConfig();
} catch (err) {
  console.error(err instanceof ConfigError ? err.message : err);
  process.exit(1);
}

console.log(`Dry run — scraping ${config.searchUrl}`);
console.log('Nothing will be sent to Slack.\n');

try {
  const { source, tweets, loginWall } = await scrapeSearch(config);
  printQuiet(`extraction path: ${source}`);

  if (loginWall) {
    printWarning('X served a login wall — X_AUTH_TOKEN / X_CSRF_TOKEN are stale. Re-copy both cookies.');
    process.exit(1);
  }

  const classified = filterAndClassify(tweets, config.ownHandle);
  printQuiet(`${tweets.length} tweets scraped, ${classified.length} after filtering out @${config.ownHandle}`);

  if (classified.length === 0) {
    printWarning('No tweets found. Either the search is genuinely empty or extraction broke.');
    process.exit(1);
  }

  console.log('');
  for (const tweet of classified) console.log(formatTweet(tweet));
  console.log(`\nLooks healthy. ${classified.length} tweets would be tracked.`);
} catch (err) {
  printWarning(`scrape failed: ${err.message}`);
  process.exit(1);
}
########## notify-terminal.mjs ##########
const C = {
  reset: '\x1b[0m',
  dim: '\x1b[2m',
  bold: '\x1b[1m',
  cyan: '\x1b[36m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
};

export const MAX_BODY = 240;

const KIND_LABEL = {
  mention: 'mention',
  reply: 'reply',
  quote: 'quote',
};

export function stripAnsi(value) {
  // eslint-disable-next-line no-control-regex
  return value.replace(/\x1b\[[0-9;]*m/g, '');
}

function stamp(date) {
  return date.toTimeString().slice(0, 8);
}

function body(text) {
  const flat = String(text).replace(/\s+/g, ' ').trim();
  return flat.length > MAX_BODY ? `${flat.slice(0, MAX_BODY - 1)}…` : flat;
}

export function formatTweet(tweet, now = new Date()) {
  const kind = KIND_LABEL[tweet.kind] ?? tweet.kind;
  return (
    `${C.dim}[${stamp(now)}]${C.reset} ${C.yellow}${C.bold}NEW MENTION${C.reset} ` +
    `${C.cyan}@${tweet.author}${C.reset} ${C.dim}·${C.reset} ${kind}\n` +
    `  ${body(tweet.text)}\n` +
    `  ${C.dim}${tweet.url}${C.reset}`
  );
}

export function printTweet(tweet) {
  console.log(formatTweet(tweet));
}

export function printStarted(pollMs, projectDir) {
  console.log(
    `${C.bold}@entirehq mention watcher started${C.reset} ` +
      `(polling every ${Math.round(pollMs / 1000)}s) ${C.dim}[${projectDir}]${C.reset}`,
  );
}

export function printBaseline(count) {
  console.log(
    `${C.dim}[${stamp(new Date())}]${C.reset} tracking ${count} existing ` +
      `${count === 1 ? 'mention' : 'mentions'} — watching for new ones`,
  );
}

export function printQuiet(message) {
